ables weep."}]},{"cov":"Süzme Kırmızı Mercimek","id":"tr_mercimek","c":"Türk Mutfağı","cat":"Çorba","d":"Çok Kolay","p":10,"k":30,"sv":4,"tr":"Süzme Mercimek Çorbası","en":"Turkish Red Lentil Soup","img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/EgFoodLentilSoup.jpg/500px-EgFoodLentilSoup.jpg","ing":[{"k":"mercimek","n":"Kırmızı Mercimek","ne":"Red Lentils","a":"1","u":"su bardağı","ue":"cup"},{"k":"sogan","n":"Soğan","ne":"Onion","a":"1","u":"adet","ue":"pcs"},{"k":"havuc","n":"Havuç","ne":"Carrot","a":"1","u":"adet","ue":"pcs"},{"k":"patates","n":"Patates","ne":"Potato","a":"1","u":"adet","ue":"pcs"},{"k":"tereyagi","n":"Tereyağı","ne":"Butter","a":"2","u":"yemek kaşığı","ue":"tbsp"},{"k":"limon","n":"Limon","ne":"Lemon","a":"1","u":"adet","ue":"pcs"}],"st":[{"o":1,"tool":"pot","sec":420,"t":"Sebzeler","i":"Soğan, havuç ve patatesi tereyağında 5 dakika çevirin.","te":"Sweat Vegetables","ie":"Stir the onion, carrot and potato in butter for 5 minutes.","p":"","pe":""},{"o":2,"tool":"pot","sec":1500,"t":"Pişirme","i":"Yıkanmış mercimeği ve 6 bardak sıcak suyu ekleyip her şey ezilecek kadar yumuşayana dek 25 dakika pişirin.","te":"Cook","ie":"Add rinsed lentils and 6 cups hot water and cook 25 minutes until everything is soft.","p":"","pe":""},{"o":3,"tool":"blender","sec":120,"t":"Pürüzsüz Yapma ve Servis","i":"Blenderdan geçirin, tuzlayıp limon sıkarak servis edin.","te":"Blend and Serve","ie":"Blend until smooth, season and finish with a squeeze of lemon.","p":"","pe":""}]},{"cov":"İmam Bayıldı","id":"tr_imambayildi","c":"Türk Mutfağı","cat":"Vegan","d":"Orta","p":30,"k":50,"sv":4,"tr":"İmam Bayıldı","en":"İmam Bayıldı (Stuffed Eggplant in Olive Oil)","img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/%C4%B0mam_bay%C4%B1ld%C4%B1_AvL.JPG/500px-%C4%B0mam_bay%C4%B1ld%C4%B1_AvL.JPG","ing":[{"k":"patlican","n":"Patlıcan","ne":"Eggplants","a":"4","u":"adet","ue":"pcs"},{"k":"sogan","n":"Soğan","ne":"Onions","a":"3","u":"adet","ue":"pcs"},{"k"