","n":"Tereyağı","ne":"Butter","a":"1","u":"yemek kaşığı","ue":"tbsp"}],"st":[{"o":1,"tool":"pot","sec":900,"t":"Muhallebi","i":"Süt, şeker, un ve nişastayı karıştırarak kaynatın, koyulaşana kadar 12 dakika pişirin.","te":"Pudding","ie":"Cook milk, sugar, rice flour and starch, stirring, until thick, about 12 minutes.","p":"","pe":""},{"o":2,"tool":"pan","sec":480,"t":"Yakma","i":"Kalın tavaya tereyağı ve 2 kaşık şeker koyup karamelleştirin, muhallebiyi dökün ve alt yüzünü koyu kahve olana kadar yakın.","te":"Caramelise","ie":"Caramelise butter and 2 tbsp sugar in a heavy pan, pour in the pudding and cook until the bottom is dark brown.","p":"Alt kısmı yanık değil, koyu karamel olmalı.","pe":"The base should be deep caramel, not burnt."},{"o":3,"tool":"plate","sec":3600,"t":"Soğutma","i":"Tavayı buzdolabında 3 saat dinlendirin, dilimleyip karamelli yüzü üste gelecek şekilde ters çevirin.","te":"Chill and Flip","ie":"Chill 3 hours, slice and flip so the caramelised side faces up.","p":"","pe":""}]},{"cov":"Tereyağlı İrmik Helvası","id":"tr_helva","c":"Türk Mutfağı","cat":"Tatlı","d":"Kolay","p":5,"k":25,"sv":6,"tr":"İrmik Helvası","en":"İrmik Helvası (Semolina Halva)","img":null,"ing":[{"k":"irmik","n":"İrmik","ne":"Semolina","a":"1.5","u":"su bardağı","ue":"cup"},{"k":"tereyagi","n":"Tereyağı","ne":"Butter","a":"100","u":"g","ue":"g"},{"k":"seker","n":"Şeker","ne":"Sugar","a":"1","u":"su bardağı","ue":"cup"},{"k":"sut","n":"Süt ve Su","ne":"Milk and Water","a":"2","u":"su bardağı","ue":"cup"},{"k":"cam","n":"Çam Fıstığı","ne":"Pine Nuts","a":"2","u":"yemek kaşığı","ue":"tbsp"}],"st":[{"o":1,"tool":"pot","sec":600,"t":"Şerbet","i":"Süt, su ve şekeri ısıtıp şeker erisin; sıcak tutun.","te":"Syrup","ie":"Warm milk, water and sugar until the sugar dissolves; keep hot.","p":"","pe":""},{"o":2,"tool":"pot","sec":900,"t":"İrmiği Kavurma","i":"Tereyağında çam fıstığı ve irmiği kısık ateşte sürekli karıştırarak 12-15 dakika kokusu çıkıp kızarana kadar kavurun.","te":"Toast t